<?php
class AccountController extends BaseController { public function index(mysqli $db): void { require_customer();$id=(int)$_SESSION['user_id'];$user=User::find($db,$id);$message='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Please enter a valid name and email.';elseif(User::emailTaken($db,$email,$id))$error='That email is already in use.';else{User::update($db,$id,$name,$email,$phone,$address);$_SESSION['username']=$name;$user=User::find($db,$id);$message='Profile updated successfully.';}}$d=$this->data($db);$d['user']=$user;$d['message']=$message;$d['error']=$error;render('customer/account',$d);} }
